def IsCoveringMap.fundamentalGroupEquivFiber [SimplyConnectedSpace E]
    (hp : IsCoveringMap p) (e : p ⁻¹' {x}) :
    FundamentalGroup X x ≃ p ⁻¹' {x}

theorem map_homotopic_of_homotopicRel {f g : C(X, Y)} (hf : f x = y) {S : Set X}
    (hx : x ∈ S) (H : f.HomotopicRel g S) (p : Ω^ N X x) :
    _root_.GenLoop.Homotopic (map f hf p) (map g ((H.fst_eq_snd hx).symm.trans hf) p)

theorem map_eq_of_homotopicRel {f g : C(X, Y)} (hf : f x = y) {S : Set X}
    (hx : x ∈ S) (H : f.HomotopicRel g S) :
    map (N := N) f hf = map g ((H.fst_eq_snd hx).symm.trans hf)

theorem mapHom_eq_of_homotopicRel [DecidableEq N] [Nonempty N] {f g : C(X, Y)}
    (hf : f x = y) {S : Set X} (hx : x ∈ S) (H : f.HomotopicRel g S) :
    mapHom (N := N) f hf = mapHom g ((H.fst_eq_snd hx).symm.trans hf)

theorem prod_homotopic {p p' : Ω^ N X x} {q q' : Ω^ N Y y}
    (hp : _root_.GenLoop.Homotopic p p') (hq : _root_.GenLoop.Homotopic q q') :
    _root_.GenLoop.Homotopic (prod p q) (prod p' q')

theorem pi_homotopic {p q : ∀ i, Ω^ N (Z i) (z i)}
    (h : ∀ i, _root_.GenLoop.Homotopic (p i) (q i)) :
    _root_.GenLoop.Homotopic (pi p) (pi q)

def prodEquiv (x : X) (y : Y) :
    HomotopyGroup N (X × Y) (x, y) ≃
      HomotopyGroup N X x × HomotopyGroup N Y y

def prodMulEquiv [DecidableEq N] [Nonempty N] (x : X) (y : Y) :
    HomotopyGroup N (X × Y) (x, y) ≃*
      HomotopyGroup N X x × HomotopyGroup N Y y

def codRestrict {s : Set X} {x y : s} (γ : Path x.val y.val)
    (hmem : ∀ t, γ t ∈ s) :
    Path x y

theorem truncateOfLE_range_subset {a b : X} (γ : Path a b) {t₀ t₁ : ℝ}
    (h : t₀ ≤ t₁) {U : Set X} (hU : Set.Icc t₀ t₁ ⊆ γ.extend ⁻¹' U) :
    Set.range (γ.truncateOfLE h) ⊆ U

theorem map_nullhomotopic_of_nullhomotopic {Y : Type*} [TopologicalSpace Y] {f : C(X, Y)}
    (hf : f.Nullhomotopic) {a : X} (γ : Path a a) :
    (γ.map (map_continuous f)).Homotopic (Path.refl (f a))

def germSection (F : X.Presheaf C) (U : Opens X)
    (s : ToType (F.obj (Opposite.op U))) :
    U → F.EtaleSpace

theorem mem_sectionRange_iff {U : Opens X} {s : ToType (F.obj (Opposite.op U))}
    {g : F.EtaleSpace} :
    g ∈ sectionRange F U s ↔ ∃ h : g.base ∈ U, g.germ = F.germ U g.base h s

def sectionOpenPartialHomeomorph (F : X.Presheaf C) (U : Opens X)
    (s : ToType (F.obj (Opposite.op U))) (x₀ : U) :
    OpenPartialHomeomorph F.EtaleSpace X
